using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;using System.Xml.Serialization;
namespace ShotOut {
partial class SettingsDialog {
    NumberField tabLimit,tabIdle;
    void AddTabOptions(FlowLayoutPanel page){AddTitle(page,"Tab switching");Toggle(page,"recentTabOrder","Ctrl+Tab cycles tabs in recently used order",Value.RecentTabOrder);SettingsHelp(page,"Hold Ctrl and press Tab to step through recently used tabs. Release Ctrl to finish. A single Ctrl+Tab switches back to your last tab; Ctrl+Shift+Tab goes in reverse. Off: cycle left to right along the tab strip.",95);AddTitle(page,"Recently closed tabs");SettingsHelp(page,"Reopen the last closed tab with Ctrl+Shift+T. Right-click the tab strip to choose among the last 20, or find them with Ctrl+K. Editable recovery copies are kept in Projects / Recently closed tabs (automatic closures use Auto-closed tabs). Recovery files remain until you delete them.",110);Toggle(page,"tabScroll","Show draggable scrollbar when tabs overflow",Value.ShowTabScrollbar);SettingsHelp(page,"Scroll over the tabs with the mouse wheel or Shift+wheel, use the arrows, or drag the bar. Ctrl+Tab goes forward; Ctrl+Shift+Tab goes back.",65);AddTitle(page,"Automatic closing (off by default)");Toggle(page,"tabAuto","Automatically close idle tabs above the tab limit",Value.AutoCloseTabs);tabLimit=NumberRow(page,"Maximum open tabs",1,200,Value.TabLimit);tabIdle=NumberRow(page,"Minimum idle age · minutes",0,1440,Value.TabIdleMinutes);Toggle(page,"tabSaved","Close saved, unmodified tabs",Value.CloseIdleSavedTabs);Toggle(page,"tabUnsaved","Close unsaved tabs (keep an editable copy)",Value.CloseIdleUnsavedTabs);SettingsHelp(page,"Oldest activity closes first. Visiting a tab, taking a screenshot, or editing refreshes its activity. The current tab is never closed. Zero minutes removes the idle-age wait. The limit can be exceeded when no eligible tabs exist.",95);SettingsHelp(page,"Unsaved tabs are closed only after an editable .shotout copy is written successfully to Projects / Auto-closed tabs. Open that copy to restore it. These copies retain original screenshot pixels and are kept until you delete them.",95);var open=Button("Open auto-closed tabs folder",260);open.Click+=delegate{try{string folder=Path.Combine(Value.ProjectFolder,"Auto-closed tabs");Directory.CreateDirectory(folder);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(folder){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open folder");}};page.Controls.Add(open);}
    void SaveTabOptions(){Value.RecentTabOrder=checks["recentTabOrder"].Checked;Value.ShowTabScrollbar=checks["tabScroll"].Checked;Value.AutoCloseTabs=checks["tabAuto"].Checked;Value.CloseIdleSavedTabs=checks["tabSaved"].Checked;Value.CloseIdleUnsavedTabs=checks["tabUnsaved"].Checked;Value.TabLimit=(int)tabLimit.Value;Value.TabIdleMinutes=(int)tabIdle.Value;}
}
partial class Editor {
    decimal? manualTextPoints;Timer tabMaintenance;bool tabMaintenanceQueued;
    static decimal AdaptiveTextPoints(Size image){return TextFonts.Points((float)Math.Max(27.5m,Math.Min(160,22m*1.25m*Math.Max(image.Width,image.Height)/1000m)));}
    void TouchTabActivity(){if(currentDocument>=0&&currentDocument<documents.Count)documents[currentDocument].LastActivityUtc=DateTime.UtcNow;}
    void InitializeTabMaintenance(){tabMaintenance=new Timer{Interval=60000};tabMaintenance.Tick+=delegate{MaintainIdleTabs(DateTime.UtcNow);};if(!Preferences.Testing)tabMaintenance.Start();Disposed+=delegate{tabMaintenance.Dispose();};}
    void ScheduleTabMaintenance(){if(Preferences.Testing||!Preferences.Current.AutoCloseTabs||tabMaintenanceQueued||!IsHandleCreated)return;tabMaintenanceQueued=true;BeginInvoke((Action)delegate{tabMaintenanceQueued=false;if(!IsDisposed)MaintainIdleTabs(DateTime.UtcNow);});}
    string ArchiveIdleTab(EditorDocument doc,bool manual=false){string folder=Path.Combine(Preferences.Current.ProjectFolder,manual?"Recently closed tabs":"Auto-closed tabs");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"Auto-closed "+DateTime.Now.ToString("yyyy-MM-dd HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8)+".shotout");var project=new Project{CreatedUtc=doc.CreatedUtc,CanvasBase=doc.CanvasBase,Background=Art.Bytes(doc.Image),Marks=doc.Marks.Select(m=>m.Clone()).ToList()};WriteFileSafely(file,stream=>new XmlSerializer(typeof(Project)).Serialize(stream,project));return file;}
    static bool TabNeedsArchive(EditorDocument d){return d.Dirty||!File.Exists(d.ImagePath)&&!File.Exists(d.ProjectPath);}
    void MaintainIdleTabs(DateTime utc){
        var p=Preferences.Current;if(recentTabCycle!=null||!p.AutoCloseTabs||documents.Count<=p.TabLimit||currentDocument<0||dragging||moving||resizing||clonePainting||inlineTarget!=null||strokeAdjusting||captureTimer!=null||OwnedForms.Any(form=>form.Visible))return;
        StoreDocument();int closed=0;while(documents.Count>p.TabLimit){var active=documents[currentDocument];var candidate=documents.Where(d=>d!=active&&!d.Welcome&&d.LastActivityUtc<=utc.AddMinutes(-p.TabIdleMinutes)).Where(d=>TabNeedsArchive(d)?p.CloseIdleUnsavedTabs:p.CloseIdleSavedTabs).OrderBy(d=>d.LastActivityUtc).FirstOrDefault();if(candidate==null)break;if(!RememberClosedTab(candidate,null,true))break;int at=documents.IndexOf(candidate);documents.RemoveAt(at);if(at<currentDocument)currentDocument--;candidate.Image.Dispose();if(candidate.CachedPreview!=null&&!Object.ReferenceEquals(candidate.CachedPreview,Preview))candidate.CachedPreview.Dispose();candidate.CachedPreview=null;closed++;}
        if(closed>0){TouchRecovery();UpdateDocumentTitles();documentStrip.Reveal(currentDocument);UpdateStatus("Closed "+closed+" idle tab(s). Unsaved tabs were kept as editable copies.");}
    }
}
}

